<?php declare(strict_types=1);require_once __DIR__.'/includes/functions.php';$lang=lang();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM projects WHERE id=?');$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);$pageTitle='Project not found';require __DIR__.'/includes/header.php';?><section class="section"><div class="container empty-state"><span class="empty-icon">✳</span><h1>Project not found</h1><p>This project may have been removed or is no longer available.</p><a class="btn primary" href="projects.php">Browse projects</a></div></section><?php require __DIR__.'/includes/footer.php';exit;}if(post()){verifyCsrf();if(isset($_POST['like']))toggleLike('project',$id);if(isset($_POST['comment'])){$u=requireVerifiedUser();$body=clean('body',2000);if($body)db()->prepare("INSERT INTO comments(user_id,content_type,content_id,body) VALUES(?,?,?,?)")->execute([$u['id'],'project',$id,$body]);}redirect('project-detail.php?id='.$id);} $comments=commentsFor('project',$id);$pageTitle=localTitle($p,$lang);require __DIR__.'/includes/header.php';?><section class="section"><div class="container"><p class="eyebrow"><?=e($p['category'])?> · <?=e($p['status'])?></p><h1 class="section-title"><?=e(localTitle($p,$lang))?></h1><?php if($p['featured_image']):?><img class="detail-image" src="<?=e($p['featured_image'])?>" alt="<?=e(localTitle($p,$lang))?>"><?php endif;?><p class="copy"><?=nl2br(e(localDescription($p,$lang)))?></p><div class="like-row"><form method="post"><?=csrfField()?><button class="like-btn" name="like">♡ Like · <?=likeCount('project',$id)?></button></form></div><div class="form-shell" style="margin:35px 0"><h2>Discussion</h2><?php if(currentUser()&&((int)currentUser()['email_verified']||currentUser()['role']==='admin')):?><form method="post"><?=csrfField()?><div class="field"><textarea name="body" placeholder="Share a comment..."></textarea></div><button class="btn primary" name="comment">Comment</button></form><?php else:?><p>Verified users can comment. <a href="login.php" style="color:var(--forest);font-weight:800">Sign in</a>.</p><?php endif;?><?php foreach($comments as $c):?><div class="comment"><b><?=e($c['full_name'])?></b><div class="comment-meta"><?=e($c['created_at'])?></div><p><?=nl2br(e($c['body']))?></p></div><?php endforeach;?></div></div></section><?php require __DIR__.'/includes/footer.php';
